template <typename T>
bool operator!=(const T& lhs, const T& rhs) {
    return !(lhs == rhs);
}

// Example User-Defined Type (Requires operator== definition)
struct CustomData {
    int id;
};

bool operator==(const CustomData& a, const CustomData& b) {
    return a.id == b.id;
}

